#!/bin/sh
# Flux Backup recovery kit: back up "rsync" (rsync) with plain rsync, without Flux.
#
#   sh flux-backup.sh             make a new snapshot
#   sh flux-backup.sh --dry-run   only show what would change
#
# It does what Flux does: hard-link unchanged files against the newest snapshot
# (--link-dest), write into snapshots/.partial (continued next time if interrupted),
# then rename it to the date and time and point "latest" at it.
# Generated by Flux Backup 0.2.0. FLUX-RECOVERY.txt explains everything else.
set -eu

DRY=
KEEP='--acls --xattrs'
if [ "${1:-}" = "--dry-run" ]; then DRY=1; KEEP=; fi
REPO=/srv/tgt/flux-rsync/fixture-host/root/rsync
mkdir -p "$REPO/snapshots/.partial/data"
RULES="$REPO/snapshots/.partial/rsync-filter.txt"
DEST="$REPO/snapshots/.partial/data/"

# Exclusion rules (rsync filter syntax; the first matching rule wins).
cat > "$RULES.profile" <<'FLUX_RULES'
# Flux Backup: exclusion rules for “rsync” (rsync)
# rsync filter rules (used with --exclude-from). The first rule that matches a
# path decides: "- " leaves it out, "+ " keeps it.

# The backup folders themselves:
- /srv/tgt/flux-rsync/***
FLUX_RULES

# Folders marked as caches (CACHEDIR.TAG) or with a no-backup marker: leave their
# contents out, as Flux does. rsync can't do this by itself.
find /srv/src -type f \( -name CACHEDIR.TAG \) 2>/dev/null | while IFS= read -r f; do
    if [ "$(basename "$f")" = CACHEDIR.TAG ]; then
        head -c 43 "$f" 2>/dev/null | grep -q '^Signature: 8a477f597d28d172789f06886806bc55' || continue
    fi
    printf -- '- %s/*\n' "$(dirname "$f" | sed 's/[][*?\\]/\\&/g')"
done > "$RULES.markers"
cat "$RULES.markers" "$RULES.profile" > "$RULES"
rm -f "$RULES.markers"
rm -f "$RULES.profile"

# The newest snapshot: unchanged files become hard links to it.
PREV=$(ls -1 "$REPO/snapshots" | grep -v '^\.' | sort | tail -n 1)
LINK=
[ -n "$PREV" ] && LINK="../../$PREV/data"

set +e
rsync $KEEP --archive --hard-links --numeric-ids --relative --delete --delete-excluded --exclude-from="$RULES" ${LINK:+"--link-dest=$LINK"} ${DRY:+--dry-run} \
    /srv/src/ \
    "$DEST"
RC=$?
set -e
case $RC in
    0) ;;
    23|24) echo "Some files could not be copied (rsync exit $RC); the snapshot is still usable." >&2 ;;
    *) echo "rsync failed (exit $RC). The unfinished snapshot is kept in snapshots/.partial; run this again to continue it." >&2
       exit "$RC" ;;
esac
[ -n "$DRY" ] && exit 0

# A new name from the date and time, made unique like Flux does (_2, _3, …).
BASE=$(date +%Y-%m-%d_%H-%M-%S)
ID=$BASE
N=2
while [ -e "$REPO/snapshots/$ID" ]; do ID="${BASE}_$N"; N=$((N + 1)); done
mv "$REPO/snapshots/.partial" "$REPO/snapshots/$ID"
ln -sfn "snapshots/$ID" "$REPO/latest"
echo "Created snapshot $REPO/snapshots/$ID"
